package cms

import (
	"context"
	"time"
)

// Renderer converts Markdown into a sanitised HTML fragment and a plain-text projection. Raw HTML
// must never survive: implementations have to disable or strip it rather than escape it after the
// fact. | Renderer 把 Markdown 转成净化后的 HTML 片段与纯文本投影。原始 HTML 绝不允许存活：
// 实现必须禁用或剥离它，而不是事后转义。
type Renderer interface {
	// Render returns sanitised HTML and the plain-text projection. | Render 返回净化后的 HTML 与纯文本投影。
	Render(markdown string) (html, text string, err error)
}

// BlobStore keeps media bytes under opaque keys. Keys are generated by the service and never carry
// a user-supplied name. | BlobStore 在不透明键下保存媒体字节。键由服务生成，绝不携带用户提供的名称。
type BlobStore interface {
	// Put writes data under key. | Put 把 data 写入 key。
	Put(ctx context.Context, key string, data []byte) error
	// Get reads the bytes stored under key. | Get 读取 key 下的字节。
	Get(ctx context.Context, key string) ([]byte, error)
	// Delete removes key; a missing key is not an error. | Delete 删除 key；键不存在不算错误。
	Delete(ctx context.Context, key string) error
}

// Store is the persistence boundary. Every method takes tenantID as its first business argument
// and every implementation must put tenant_id into the SQL condition: a cross-tenant identifier is
// indistinguishable from a missing one. | Store 是持久化边界。每个方法都以 tenantID 作为第一个业务参数，
// 每个实现都必须把 tenant_id 写进 SQL 条件：跨租户标识与不存在的标识不可区分。
type Store interface {
	// ListCategories returns every category of the tenant. | ListCategories 返回租户的全部分类。
	ListCategories(ctx context.Context, tenantID string) ([]Category, error)
	// GetCategory returns one category or ErrCategoryNotFound. | GetCategory 返回一个分类或 ErrCategoryNotFound。
	GetCategory(ctx context.Context, tenantID, id string) (Category, error)
	// GetCategoryBySlug returns one category by slug or ErrCategoryNotFound. | GetCategoryBySlug 按别名返回分类或 ErrCategoryNotFound。
	GetCategoryBySlug(ctx context.Context, tenantID, slug string) (Category, error)
	// CreateCategory inserts a category. | CreateCategory 插入一个分类。
	CreateCategory(ctx context.Context, tenantID string, category Category) error
	// UpdateCategory replaces the editable fields of one category. | UpdateCategory 替换一个分类的可编辑字段。
	UpdateCategory(ctx context.Context, tenantID string, category Category) error
	// MoveCategory rewrites the moved category and every descendant path in one transaction, re-reading
	// and locking the destination parent before the rewrite. | MoveCategory 在一个事务中重写被移动分类及其
	// 全部后代的路径，重写前重新读取并锁定目标父分类。
	MoveCategory(ctx context.Context, tenantID string, category Category, expectedPath string) error
	// DeleteCategoryIfEmpty deletes a category only while it still has no children or articles, inside one
	// transaction. | DeleteCategoryIfEmpty 在一个事务中仅当分类仍无子分类与文章时删除它。
	DeleteCategoryIfEmpty(ctx context.Context, tenantID, id string) error
	// CountCategoryChildren counts direct child categories. | CountCategoryChildren 统计直接子分类数。
	CountCategoryChildren(ctx context.Context, tenantID, id string) (int64, error)
	// CountArticlesByCategories counts non-deleted articles directly assigned to each category. |
	// CountArticlesByCategories 统计直接归属每个分类的未删除文章数。
	CountArticlesByCategories(ctx context.Context, tenantID string, categoryIDs []string) (map[string]int64, error)
	// CountPublicArticlesByCategories counts only published, public, due articles. |
	// CountPublicArticlesByCategories 只统计已发布、公开且已到发布时间的文章。
	CountPublicArticlesByCategories(ctx context.Context, tenantID string, categoryIDs []string, now time.Time) (map[string]int64, error)

	// CreateArticle inserts an article. | CreateArticle 插入一篇文章。
	CreateArticle(ctx context.Context, tenantID string, article Article) error
	// CreateArticleWithTags inserts an article and replaces its tag links in one transaction. |
	// CreateArticleWithTags 在一个事务中插入文章并替换其标签连接。
	CreateArticleWithTags(ctx context.Context, tenantID string, article Article, tags []Tag) error
	// UpdateArticleContent replaces the content fields of one article, guarded by the expected version. |
	// UpdateArticleContent 替换一篇文章的内容字段，并以期望版本作为并发前置条件。
	UpdateArticleContent(ctx context.Context, tenantID string, article Article, expectedVersion int) error
	// UpdateArticleContentWithTags updates the content and replaces the tag links in one transaction. |
	// UpdateArticleContentWithTags 在一个事务中更新内容并替换标签连接。
	UpdateArticleContentWithTags(ctx context.Context, tenantID string, article Article, expectedVersion int, tags []Tag) error
	// UpdateArticleStatus applies one lifecycle status change, guarded by the expected current status. |
	// UpdateArticleStatus 应用一次生命周期状态变更，并以期望的当前状态作为并发前置条件。
	UpdateArticleStatus(ctx context.Context, tenantID, id string, expectedStatus, status ArticleStatus, publishAt *time.Time, updatedAt time.Time) error
	// GetArticle returns one article or ErrArticleNotFound. | GetArticle 返回一篇文章或 ErrArticleNotFound。
	GetArticle(ctx context.Context, tenantID, id string) (Article, error)
	// GetArticleBySlug returns one article by slug or ErrArticleNotFound. | GetArticleBySlug 按别名返回文章或 ErrArticleNotFound。
	GetArticleBySlug(ctx context.Context, tenantID, slug string) (Article, error)
	// ListArticles returns a decorated page. | ListArticles 返回装饰后的一页文章。
	ListArticles(ctx context.Context, tenantID string, filter ArticleFilter) (ArticlePage, error)
	// ArticleTags returns the tags of one article. | ArticleTags 返回一篇文章的标签。
	ArticleTags(ctx context.Context, tenantID, articleID string) ([]Tag, error)
	// ArticlesTags batches tags for a set of articles. | ArticlesTags 批量返回一组文章的标签。
	ArticlesTags(ctx context.Context, tenantID string, articleIDs []string) (map[string][]Tag, error)
	// IncrementArticleViews adds one to the view counter. | IncrementArticleViews 把浏览量加一。
	IncrementArticleViews(ctx context.Context, tenantID, id string) error
	// SoftDeleteArticle marks an article deleted and rewrites its slug for reuse. |
	// SoftDeleteArticle 标记文章已删除并改写其别名以便复用。
	SoftDeleteArticle(ctx context.Context, tenantID, id string, deletedAt time.Time, slug string) error
	// RelatedArticles returns published articles in the same categories, excluding the article itself. |
	// RelatedArticles 返回同分类的已发布文章，排除文章本身。
	RelatedArticles(ctx context.Context, tenantID, articleID string, categoryIDs []string, now time.Time, limit int) ([]ArticleView, error)
	// Counts returns the dashboard aggregate. | Counts 返回概览聚合。
	Counts(ctx context.Context, tenantID string) (Counts, error)

	// CreateRevision inserts an immutable snapshot. | CreateRevision 插入不可变快照。
	CreateRevision(ctx context.Context, tenantID string, revision Revision) error
	// ListRevisions returns revisions newest first. | ListRevisions 按从新到旧返回修订。
	ListRevisions(ctx context.Context, tenantID, articleID string) ([]Revision, error)
	// GetRevision returns one revision or ErrRevisionNotFound. | GetRevision 返回一份修订或 ErrRevisionNotFound。
	GetRevision(ctx context.Context, tenantID, articleID, revisionID string) (Revision, error)
	// PruneRevisions keeps the newest keep revisions and deletes older ones. | PruneRevisions 保留最新 keep 份修订并删除更旧的。
	PruneRevisions(ctx context.Context, tenantID, articleID string, keep int) error

	// ListTags returns tags, optionally filtered by keyword. | ListTags 返回标签，可按关键词过滤。
	ListTags(ctx context.Context, tenantID, keyword string) ([]Tag, error)
	// GetTag returns one tag or ErrTagNotFound. | GetTag 返回一个标签或 ErrTagNotFound。
	GetTag(ctx context.Context, tenantID, id string) (Tag, error)
	// GetTagBySlug returns one tag by slug or ErrTagNotFound. | GetTagBySlug 按别名返回标签或 ErrTagNotFound。
	GetTagBySlug(ctx context.Context, tenantID, slug string) (Tag, error)
	// CreateTag inserts a tag. | CreateTag 插入一个标签。
	CreateTag(ctx context.Context, tenantID string, tag Tag) error
	// UpdateTag replaces the editable fields of one tag. | UpdateTag 替换一个标签的可编辑字段。
	UpdateTag(ctx context.Context, tenantID string, tag Tag) error
	// DeleteTagIfUnused deletes a tag only while no non-deleted article carries it, inside one transaction. |
	// DeleteTagIfUnused 在一个事务中仅当没有未删除文章携带该标签时删除它。
	DeleteTagIfUnused(ctx context.Context, tenantID, id string) error
	// CountArticlesOfTag counts non-deleted articles carrying the tag. | CountArticlesOfTag 统计携带该标签的未删除文章数。
	CountArticlesOfTag(ctx context.Context, tenantID, id string) (int64, error)

	// CreateMedia inserts a media record. | CreateMedia 插入一条媒体记录。
	CreateMedia(ctx context.Context, tenantID string, media Media) error
	// GetMedia returns one media record or ErrMediaNotFound. | GetMedia 返回一条媒体记录或 ErrMediaNotFound。
	GetMedia(ctx context.Context, tenantID, id string) (Media, error)
	// ListMedia returns a page of media. | ListMedia 返回一页媒体。
	ListMedia(ctx context.Context, tenantID string, filter MediaFilter) (MediaPage, error)
	// DeleteMedia removes a media record. | DeleteMedia 删除一条媒体记录。
	DeleteMedia(ctx context.Context, tenantID, id string) error

	// CreateComment inserts a comment. | CreateComment 插入一条评论。
	CreateComment(ctx context.Context, tenantID string, comment Comment) error
	// GetComment returns one comment or ErrCommentNotFound. | GetComment 返回一条评论或 ErrCommentNotFound。
	GetComment(ctx context.Context, tenantID, id string) (Comment, error)
	// ListComments returns a decorated page of comments. | ListComments 返回装饰后的一页评论。
	ListComments(ctx context.Context, tenantID string, filter CommentFilter) (CommentPage, error)
	// UpdateComment replaces the moderation state and body of one comment. | UpdateComment 替换一条评论的审核状态与正文。
	UpdateComment(ctx context.Context, tenantID string, comment Comment) error
	// CountComments counts comments by article and status; an empty articleID counts the tenant. |
	// CountComments 按文章与状态统计评论；articleID 为空时统计整个租户。
	CountComments(ctx context.Context, tenantID, articleID string, status CommentStatus) (int64, error)

	// GetSettings returns the tenant settings or ErrNotFound. | GetSettings 返回租户设置或 ErrNotFound。
	GetSettings(ctx context.Context, tenantID string) (Settings, error)
	// SaveSettings upserts the tenant settings. | SaveSettings 插入或更新租户设置。
	SaveSettings(ctx context.Context, tenantID string, settings Settings) error

	// AddAudit appends one audit entry. | AddAudit 追加一条审计记录。
	AddAudit(ctx context.Context, tenantID string, entry AuditEntry) error
	// ListAudit returns a page of audit entries. | ListAudit 返回一页审计记录。
	ListAudit(ctx context.Context, tenantID string, filter AuditFilter) (AuditPage, error)
}
